CUES['TLVUjSOUWXk'] = [
(4.18,6.18,"Dobro, dobro, šta ti je?","Ну ладно, ладно, что с тобой?","Okay, okay, what's wrong with you?"),
(6.18,7.18,"Šta sam sad uradio?","Что я опять сделал?","What did I do now?"),
(7.18,10.18,"Šta sam ti kriv, Bože dragi?","В чём я перед тобой виноват, Боже мой?","What did I do to you, dear God?"),
(11.18,16.18,"Ja se tebi više ne sviđam, ja tebi više nisam privlačna, debela sam, imam bore i to je to.","Я тебе больше не нравлюсь, я тебе больше не привлекательна, я толстая, у меня морщины, и всё тут.","You don't like me anymore, I'm not attractive to you anymore, I'm fat, I have wrinkles and that's that."),
(16.18,17.18,"Nije tako, nije tako.","Это не так, это не так.","That's not true, that's not true."),
(17.18,21.18,"Pa tako je, tako je, uopšte me više ne maziš kao ranije.","Да так, так, ты меня вообще больше не ласкаешь, как раньше.","Yes it is, it is, you don't cuddle me at all anymore like you used to."),
(21.18,23.18,"Ja te ne mazim? Nikog u životu nisam mazio kao tebe.","Я тебя не ласкаю? Никого в жизни я так не ласкал, как тебя.","I don't cuddle you? I've never cuddled anyone in my life like I cuddled you."),
(23.18,27.18,"Molim te, znaš ti kako si me ranije mazio, koliko si me mazio i koliko sam uživala.","Пожалуйста, ты знаешь, как ты меня раньше ласкал, сколько ласкал и как мне это нравилось.","Please, you know how you used to cuddle me, how much you cuddled me and how much I enjoyed it."),
(27.18,29.18,"Ovo je sad ništa, užas.","А сейчас это ничто, ужас.","This now is nothing, it's awful."),
(29.18,32.96,"Pritom sam čitala da ženi treba dnevno minimum osamnaest malih maženja.","К тому же я читала, что женщине нужно в день минимум восемнадцать маленьких ласк.","Besides, I read that a woman needs at least eighteen little cuddles a day."),
(33.36,36.92,"Molim te, objasni mi, šta znači osamnaest malih maženja?","Объясни мне, пожалуйста, что значит восемнадцать маленьких ласк?","Please explain to me, what do eighteen little cuddles mean?"),
(36.94,40.36,"Pa šta tu ne razumeš? Osamnaest maženja, malih.","А что тут непонятного? Восемнадцать ласк, маленьких.","What is there not to understand? Eighteen cuddles, little ones."),
(40.6,46.52,"Znači, pomaziš me po obrazu, to je jedno, pa recimo poljubiš me, drugo, pa me zagrliš, treće, pa mi češkaš rukicu, četvrto,","Значит, погладишь меня по щеке — это раз, потом, скажем, поцелуешь — два, потом обнимешь — три, потом почешешь ручку — четыре,","So, you stroke my cheek, that's one, then say you kiss me, two, then you hug me, three, then you scratch my little hand, four,"),
(46.82,53.46,"pa mi pomaziš leđa, peto, pa malo po nogici, pa nešto tu oko uvceta, razumeš.","потом погладишь спину — пять, потом немного ножку, потом что-нибудь вот тут возле ушка, понимаешь.","then you stroke my back, five, then a bit on my little leg, then something here around my little ear, you get it."),
(53.46,59.18,"Pa onda leptirić, recimo, poljubac trepavicama, to je tako jedno po jedno, pa minimum osamnaest.","Потом бабочка, например, поцелуй ресничками — вот так одно за другим, и минимум восемнадцать.","Then a butterfly kiss, say, with eyelashes, it goes one by one, and that makes at least eighteen."),
(62.56,66.94,"Bre, ta maženja moram da učim kao koreografiju?","Эти ласки мне что, учить, как хореографию?","Man, do I have to learn those cuddles like choreography?"),
(67.94,74.36,"Može li tih osamnaest maženja da zameni jedno veliko seksi maženje?","А можно эти восемнадцать ласк заменить одной большой сексуальной лаской?","Can those eighteen cuddles be replaced by one big sexy cuddle?"),
(75.3,77.58,"Pa ne može. – Pa što? – Pa ne može.","Нет, нельзя. — Почему? — Нельзя.","Well, no. – Why? – No, it can't."),
(80.16,85.94,"Pa ajde s tobom, bre. Pa ja te još mazim. A šta ja dobijem od tebe, majke mi?","Да ну тебя. Я ведь тебя ещё и ласкаю. А что я получаю от тебя, ей-богу?","Oh, come on. I still cuddle you. And what do I get from you, I swear?"),
(86.5,91.74,"Masiranje mozga i neke te priče: ti ne možeš ovoliko, ti možeš onoliko.","Массаж мозга и какие-то разговоры: ты не можешь столько, ты можешь столько.","Brain massage and all those stories: you can't do this much, you can do that much."),
(91.86,96.9,"A šta znači masiranje mozga? – Eto to, to znači. – Šta to, to? – Eto to, to.","А что значит «массаж мозга»? — Вот это и значит. — Что «это»? — Вот это.","And what does brain massage mean? – This, this is what it means. – What this? – This, this."),
(99.21,100.21,"Mazi me sad, ajde.","Ласкай меня сейчас, давай.","Cuddle me now, come on."),
(104.83,105.61,"Ajde, ljubavi.","Давай, любимая.","Come on, my love."),
]
CUES['vBFoKok2AwA'] = [
(12.48,19.24,"E, dobro. Ljudi, znate šta sam mislila? Napravila sam jedan lagan plan za ove naše dane, za danas.","Ну хорошо. Люди, знаете, что я придумала? Я составила лёгкий план на наши дни, на сегодня.","Okay, well. People, you know what I thought? I made an easy plan for our days, for today."),
(19.9,29.86,"Dakle, deco, najopuštenije, krećemo od bazena. Sunčanje je do 12.30. Molim vas, mazanje kremom na svakih 15 minuta.","Итак, дети, самым расслабленным образом, начинаем с бассейна. Загораем до 12:30. Прошу вас, мазаться кремом каждые 15 минут.","So, kids, as relaxed as possible, we start at the pool. Sunbathing is until 12:30. Please apply sunscreen every 15 minutes."),
(30.0,35.16,"Imate od 50 do 30 faktora, birajte kome šta odgovara. Najkasnije do 12.45.","Фактор у вас от 50 до 30, выбирайте, кому что подходит. Самое позднее до 12:45.","You have factors from 50 to 30, choose whatever suits you. By 12:45 at the latest."),
(35.48,43.38,"Molim te, nema skakanja u bazen, molim vas, i da znate, pločice su jako klizave, proverila sam, vodite računa.","Пожалуйста, никаких прыжков в бассейн, и знайте, плитка очень скользкая, я проверила, будьте осторожны.","Please, no jumping into the pool, and you should know, the tiles are very slippery, I checked, be careful."),
(43.5,45.84,"Okej, posle bazena prelazimo na ručak.","Хорошо, после бассейна переходим к обеду.","Okay, after the pool we move on to lunch."),
(46.38,51.0,"Lagan ručak predlažem zbog temperature, neće nam prijati, ipak treba da se navikne stomak.","Предлагаю лёгкий обед из-за жары, нам будет нехорошо, всё-таки желудку нужно привыкнуть.","I suggest a light lunch because of the heat, it won't do us good, the stomach still needs to get used to it."),
(51.32,56.76,"Posle toga idemo na stoni tenis, okej, i do četiri igramo stoni tenis.","После этого идём играть в настольный теннис, окей, и до четырёх играем в настольный теннис.","After that we go to table tennis, okay, and we play table tennis until four."),
(56.76,60.14,"Prvo igramo pojedinačno, a onda u parovima.","Сначала играем по одному, а потом парами.","First we play singles, and then in pairs."),
(60.48,64.36,"Naravno, krećemo po azbučnom redu. Je li to okej?","Конечно, начинаем по алфавиту. Это окей?","Of course, we start in alphabetical order. Is that okay?"),
(64.96,68.64,"Dobro, idemo dalje, znači do četiri. Prelazimo na remi.","Хорошо, идём дальше, значит, до четырёх. Переходим к ремми.","Good, let's move on, so until four. We move on to rummy."),
(69.18,74.92,"Lagana igra, da prosto malo spustimo tonus, da malo razmrdamo moždane vijuge.","Лёгкая игра, чтобы просто немного снизить тонус и размять извилины.","An easy game, just to lower the tone a little and get our brains moving."),
(75.02,77.44,"Samo sekund, nisam završila, samo trenutak.","Секунду, я не закончила, одну минутку.","Just a second, I haven't finished, just a moment."),
(77.68,80.74,"Dakle, remi dva sata, ne duže od toga, molim vas. Okej?","Итак, ремми два часа, не дольше, пожалуйста. Окей?","So, rummy for two hours, no longer than that, please. Okay?"),
(81.12,84.4,"Igraće gubitnik s pobednikom, pobednik s gubitnikom.","Играть будут проигравший с победителем, победитель с проигравшим.","The loser will play the winner, the winner the loser."),
(84.4,92.0,"Imam ja sve šemu, pokazaću vam posle, da popunite. E, onda posle toga, ljudi, ali stvarno, svako u svoju sobu, obavezno,","У меня всё есть в схеме, я потом вам покажу, чтобы вы заполнили. А потом, люди, правда, каждый в свою комнату, обязательно,","I have the whole scheme, I'll show you later so you can fill it in. And then after that, people, seriously, everyone to their own room, a must,"),
(92.0,98.12,"mobilni telefon je na recepciji. Dremež, kafica, unutra u sobi, možda da čitate šta god hoćete,","мобильный телефон на ресепшене. Сон, кофеёк, внутри, в комнате, можно почитать, что хотите,","mobile phone at the reception. A nap, a coffee, inside in the room, maybe read whatever you want,"),
(98.12,104.52,"zaista fakultativno, mislim 45 minuta po vašem izboru, ali direktno posle 45 minuta ne smete da kasnite, čekam vas na večeri.","совершенно по желанию, я имею в виду 45 минут на ваш выбор, но ровно через 45 минут вы не должны опаздывать, жду вас на ужине.","completely optional, I mean 45 minutes of your choice, but right after 45 minutes you must not be late, I'll be waiting for you at dinner."),
(104.52,112.06,"Okej, i na večeri ne sme da se preteruje, zato što sutra imamo plan od ranog jutra i ne smemo da kasnimo.","Окей, и на ужине нельзя перебарщивать, потому что завтра у нас план с раннего утра и мы не можем опаздывать.","Okay, and at dinner no overdoing it, because tomorrow we have a plan from early morning and we mustn't be late."),
(112.06,114.04,"Čekaj, stani, stani, polako.","Подожди, стой, стой, помедленнее.","Wait, stop, stop, slow down."),
(129.97,132.97,"Pa ne, ne, ne, čekaj, ne razumem, šta vam se ne sviđa?","Нет, нет, нет, подождите, я не понимаю, что вам не нравится?","No, no, no, wait, I don't understand, what is it you don't like?"),
(133.33,141.21,"Izvinite, da pitam, možemo li mi da imamo malo vremena za sebe? Mislim, glupo je da stalno budemo zajedno.","Простите, можно спросить, можно ли нам иметь немного времени для себя? Я имею в виду, глупо всё время быть вместе.","Excuse me, may I ask, could we have a little time for ourselves? I mean, it's silly to be together all the time."),
(141.93,146.85,"Ne, ne, ali ljudi, ja sam mislila da ćete vi da pišete, jer vi niste zapamtili raspored.","Нет-нет, но, люди, я думала, что вы будете записывать, потому что вы не запомнили расписание.","No, no, but people, I thought you would write it down, because you haven't memorized the schedule."),
(147.19,151.25,"Znači: ručak, stoni tenis, remi, pa dremež.","Значит: обед, настольный теннис, ремми, потом сон.","So: lunch, table tennis, rummy, then a nap."),
(151.47,153.29,"Znači, čekaj, pet minuta imate za sebe, šta ćete više?","Значит, подожди, у вас пять минут для себя, зачем вам больше?","So, wait, you have five minutes for yourselves, what more do you need?"),
(153.39,155.57,"Evo, svakom papir, ipak zapišite.","Вот, каждому бумагу, всё-таки запишите.","Here, a paper for everyone, write it down after all."),
(157.39,160.99,"Raspored morate da znate, da biste znali. Zapiši, ljubavi.","Расписание нужно знать, чтобы знать. Запиши, любимый.","You have to know the schedule, so that you know. Write it down, love."),
(161.15,162.37,"Evo, podeli svima.","Вот, раздай всем.","Here, hand it out to everyone."),
(162.79,168.25,"Sad ću ja da vam nađem olovke. E, pišite.","Сейчас я найду вам карандаши. Так, пишите.","I'll find you some pencils now. Right, write."),
(169.23,171.45,"Dobro, evo, Maki ću ja zapisati. Maki, znaš da pišeš, ljubavi?","Хорошо, вот, Маки я запишу сама. Маки, ты умеешь писать, любимый?","Okay, here, I'll write down Maki myself. Maki, do you know how to write, love?"),
(171.85,173.69,"Dobro, znači, zapišite raspored.","Хорошо, значит, запишите расписание.","Okay, so, write down the schedule."),
(174.11,176.13,"Dremež. – Otkad?","Сон. — С каких пор?","A nap. – Since when?"),
]
CUES['l-t7PyL2cbg'] = [
(0.59,9.71,"Anđelka, znaš šta? Gledao sam jedan dokumentarac o tome kako svaki čovek ima psihičko ili fizičko svojstvo neke životinje.","Анджелка, знаешь что? Я смотрел один документальный фильм о том, что у каждого человека есть психическое или физическое свойство какого-нибудь животного.","Andjelka, you know what? I watched a documentary about how every person has a mental or physical trait of some animal."),
(10.21,12.07,"Stvarno? – Majke mi, to je naučno dokazano.","Правда? — Честное слово, это научно доказано.","Really? – I swear, it's scientifically proven."),
(12.33,16.35,"Stvarno? Znaš, ja baš osećam da sam ja neki panter.","Правда? Знаешь, я прямо чувствую, что я какая-то пантера.","Really? You know, I really feel that I'm some kind of panther."),
(16.63,19.89,"Šta si ti rekla? – Panter. – Ti si panter? – Ma, mačka.","Кем ты себя назвала? — Пантера. — Ты пантера? — Да ну, кошка.","What did you say you are? – A panther. – You're a panther? – Come on, a cat."),
(20.19,26.61,"Panter je, bre, hrabar, vižljast, brzo trči, brzo razmišlja, inteligentan, jede meso.","Пантера, ну, храбрая, поджарая, быстро бегает, быстро соображает, умная, ест мясо.","A panther is, well, brave, lean, runs fast, thinks fast, intelligent, eats meat."),
(26.61,29.93,"Ti jedeš meso jednom nedeljno. Ti u stvari stalno jedeš samo povrće.","Ты ешь мясо раз в неделю. Ты на самом деле постоянно ешь одни овощи.","You eat meat once a week. In fact you only ever eat vegetables."),
(31.31,36.41,"Pa dobro, možda sam nešto malo elegantnije. Neka labudica.","Ну ладно, может, я что-то поэлегантнее. Какая-нибудь лебёдушка.","Well, okay, maybe I'm something a bit more elegant. Some little swan."),
(37.27,40.97,"Anđe, nemoj da se ljutiš, ali daleko si ti od labuda.","Андже, не обижайся, но ты далека от лебедя.","Andje, don't be angry, but you're far from a swan."),
(41.49,48.63,"Što? – Labud je, bre, otmen, gospodstven, ide uvek u jednom pravcu, istom brzinom, smiren. Ti, bre, ne znaš gde ćeš, levo ili desno.","Что? — Лебедь, понимаешь, изящный, благородный, всегда идёт в одном направлении, с одной скоростью, спокойный. А ты не знаешь, куда тебе, налево или направо.","What? – A swan is elegant, noble, always goes in one direction, at the same speed, calm. You don't know where you're going, left or right."),
(49.07,50.55,"Histerična žena, nikakav labud.","Истеричная женщина, а никакой не лебедь.","A hysterical woman, not a swan."),
(51.07,54.41,"Pa dobro, šta sam onda? Baš me zanima, evo, po tebi šta sam.","Ну ладно, и кто я тогда? Мне прямо интересно, вот, по-твоему, кто я.","Well, okay, what am I then? I'm really curious, so, what am I according to you."),
(54.57,58.63,"Ako ćeš iskreno... Samo da se ne ljutiš.","Если честно... Только чтобы ты не обижалась.","If you want me to be honest... Just don't get angry."),
(59.57,62.57,"Ti si, ljubavi, foka. I to beba foka.","Ты, любимая, тюлень. И притом детёныш тюленя.","You, my love, are a seal. And a baby seal at that."),
(63.05,69.03,"Što? – Pa znači, ti imaš te velike buljave oči, pa si onda slatkasta kao fokica, razumeš?","Что? — Ну, у тебя эти большие выпученные глаза, и ты сладенькая, как тюленёнок, понимаешь?","What? – Well, you have those big bulging eyes, and you're sweet like a little seal, you get it?"),
(69.21,74.85,"Onda ovako leži, vidi, ovako leži nesposobna, čeka da joj neko nešto da, tako i ti isto, razumeš?","Потом вот так лежит, смотри, вот так лежит беспомощная, ждёт, что ей кто-нибудь что-нибудь даст, так и ты, понимаешь?","Then it lies like this, look, lies like this helpless, waiting for someone to give it something, and so do you, you get it?"),
(75.07,81.11,"Onda njih treba uvek da paziš, da maziš, da se brineš, inače će da riknu.","А за ними надо всегда присматривать, ласкать, заботиться, иначе они погибнут.","And you always have to watch over them, cuddle them, take care of them, otherwise they'll croak."),
(81.43,86.67,"Tako da si ti, veruj mi, beba foka, i to je bolje, veruj mi, nego baba foka.","Так что ты, поверь мне, детёныш тюленя, и это лучше, поверь мне, чем бабка-тюлень.","So you are, believe me, a baby seal, and that's better, believe me, than a granny seal."),
(86.97,92.24,"Budi srećna. A ti, čoveče, ti si isti gorila, majke mi.","Будь счастлива. А ты, дружище, ты вылитая горилла, ей-богу.","Be happy. And you, man, you're exactly a gorilla, I swear."),
(92.46,96.26,"Pa nisam dlakav, bre. – Šta ako nisi dlakav, kakve to veze ima, imaš sva druga svojstva.","Да я не волосатый. — И что, что не волосатый, при чём тут это, у тебя все остальные свойства.","But I'm not hairy. – So what if you're not hairy, what does it matter, you have all the other traits."),
(96.72,102.16,"Velika debela zver koja samo sedi i gleda druge žene, čačka nos, češe jaja, ti si gorila.","Большой толстый зверь, который только сидит и смотрит на других женщин, ковыряет в носу, чешет яйца, ты горилла.","A big fat beast that just sits and looks at other women, picks its nose, scratches its balls, you're a gorilla."),
(102.38,106.36,"Tako da, ljubavi, sad idemo da gledamo majmune, da se upoznamo sa familijom.","Так что, любимый, сейчас пойдём смотреть на обезьян, познакомимся с роднёй.","So, love, now we're going to look at the monkeys, to meet the family."),
(108.36,110.84,"Nemoj ti nju da slušaš, bre.","Ты её не слушай.","Don't you listen to her."),
(111.18,113.2,"Tvoj brat je, bre, lav.","Твой брат — лев.","Your brother is a lion."),
(121.62,124.5,"Ništa ga ne slušaj. Ajde, skači u bazen da se družiš sa familijom malo, molim te.","Ничего его не слушай. Давай, прыгай в бассейн, пообщайся немного с роднёй, прошу.","Don't listen to him at all. Come on, jump in the pool to hang out with the family a bit, please."),
(126.44,128.22,"I majke mi, daćemo ti ribu da jedeš.","И ей-богу, мы дадим тебе рыбу поесть.","And I swear, we'll give you fish to eat."),
]
CUES['K2fyqgV-x2A'] = [
(9.46,12.46,"Pa daj, pomozi mi nešto, čoveče.","Ну давай, помоги мне хоть чем-нибудь, человек.","Come on, help me with something, man."),
(12.46,13.46,"Dobro, izvini.","Хорошо, извини.","Okay, sorry."),
(13.46,15.46,"Svaki put samo: izvini.","Каждый раз только: извини.","Every time it's just: sorry."),
(15.46,18.46,"Dobro, šta hoćeš da ti pomognem? – Pa nešto uradi, ajde.","Ладно, чем тебе помочь? — Ну сделай что-нибудь, давай.","Okay, what do you want me to help with? – Well, do something, come on."),
(18.46,19.46,"Hoćeš da iseckam ovaj krastavac?","Хочешь, я нарежу этот огурец?","Do you want me to cut this cucumber?"),
(19.46,23.46,"Nemoj krastavac, nemoj krastavac da mi diraš, zato što uvek debelo seckaš i posle mi to ne bude dobro.","Не огурец, не трогай мне огурец, потому что ты всегда режешь толсто, и потом у меня получается нехорошо.","Not the cucumber, don't touch my cucumber, because you always cut it thick and then it doesn't turn out well."),
(23.46,26.46,"Evo, paradajz. – Paradajz.","Вот, помидор. — Помидор.","Here, a tomato. – A tomato."),
(35.9,39.9,"Kako hoćeš da ti ovo isečem? – Ne tako, ne možeš tako da sečeš, gledaj.","Как ты хочешь, чтобы я это нарезал? — Не так, так резать нельзя, смотри.","How do you want me to cut this? – Not like that, you can't cut like that, look."),
(42.18,45.22,"Andrija, ne možeš paradajz da seckaš tako sitno.","Андрия, нельзя резать помидор так мелко.","Andrija, you can't chop a tomato so finely."),
(45.22,49.38,"To će samo da se napravi neka bljuzgavica u salati, sve sam sok.","Получится одна какая-то жижа в салате, один сок.","It'll just turn into some kind of slush in the salad, all juice."),
(49.38,55.86,"Znači, onako fino za salatu, malo krupnije.","Значит, красиво для салата, чуть покрупнее.","So, nicely for a salad, a bit coarser."),
(55.86,59.86,"Ovako. Dovoljno. Ovako.","Вот так. Достаточно. Вот так.","Like this. Enough. Like this."),
(59.86,61.94,"Šta to radiš? – A šta ti radiš?","Что ты делаешь? — А ты что делаешь?","What are you doing? – And what are you doing?"),
(61.94,63.82,"Što, mogu i na pola da ti stavim u salatu?","Что, могу и пополам тебе в салат положить?","What, can I put it in the salad in halves?"),
(63.82,65.82,"Pa čoveče, seci normalno, na kriške.","Ну, человек, режь нормально, кружочками.","Come on, man, cut normally, into slices."),
(68.61,71.11,"Ne, ne vredi. Uništio si poslednji paradajz.","Нет, бесполезно. Ты испортил последний помидор.","No, it's no use. You ruined the last tomato."),
(72.87,75.97,"A što se ti vrzmaš po kuhinji? – A što se ti vrzmaš, ljubavi?","А ты что ходишь по кухне кругами? — А ты что тут крутишься, любимая?","And why are you hanging around the kitchen? – And why are you hanging around, love?"),
(81.79,82.43,"Sama ću.","Я сама.","I'll do it myself."),
]
